import Image from "next/image";
import Headings from "./Headings";
import AnimateOnScroll from "@/hooks/AnimateOnScroll";

interface SectionHeadingDescProps {
  title?: string;
  subTitle?: string;

  level?: 1 | 2 | 3 | 4 | 5 | 6; // base level (title)
  subLevel?: 2 | 3 | 4 | 5 | 6; // optional override

  textCenter?: boolean;
  mdTextCenter?: boolean;
  smTextCenter?: boolean;
  titleColor?: string;
  subTitleColor?: string;
  wrapperClassName?: string;
  titleClassName?: string;
  subTitleClassName?: string;
  line?: boolean;
  line2?: boolean;
  logo?: boolean;
  fontPrimary?: boolean;
  description?: string;
  descriptionClassName?: string;
}

const SectionHeading: React.FC<SectionHeadingDescProps> = ({
  title,
  subTitle,
  line = false,
  line2 = false,
  textCenter = line ? true : false,
  titleColor,
  subTitleColor,
  smTextCenter = false,
  mdTextCenter = false,
  wrapperClassName = "",
  titleClassName = "",
  subTitleClassName = "",
  logo = false,
  level,
  subLevel,
  fontPrimary = false,
  description,
  descriptionClassName,
}) => {
  const titleLevel = level ?? 2;
  const subTitleLevel = subLevel ?? Math.min(titleLevel + 1, 6);

  return (
    <AnimateOnScroll direction="bottom">
      <div className={`flex flex-col gap-2 line ${wrapperClassName}`}>
        <div
          className={`${line && "flex items-center flex-col md:gap-7 gap-3 mx-auto"} ${logo && "flex max-md:flex-col items-center gap-4 mx-auto"}`}
        >
          {title && (
            <Headings
              level={titleLevel}
              heading={title}
              className={`${titleClassName} ${mdTextCenter ? "md:text-center" : ""
                } ${textCenter ? "text-center" : ""} ${smTextCenter ? "max-md:text-center" : ""
                } ${titleColor ? `text-${titleColor}` : "text-primary"
                } md:text-5xl/tight text-[2rem] font-primary uppercase ${fontPrimary ? "primary-font" : "secondary-font"}`}
            />
          )}
          {description && (
            <p
              className={`text-[1.063rem] ${fontPrimary ? "primary-font" : "secondary-font"}  ${mdTextCenter ? "md:text-center" : ""} ${textCenter ? "text-center" : ""} ${smTextCenter ? "max-md:text-center" : ""} ${descriptionClassName}`}
            >
              {description}
            </p>
          )}
          {logo && (
            <div className="w-16 aspect-square relative">
              <Image
                src={"/logo-2.png"}
                alt="logo"
                fill
                className="object-cover"
              />
            </div>
          )}
          {line && (
            <span className="lg:block hidden">
              <LineIcon />
            </span>
          )}
          {line && (
            <span className="lg:hidden">
              <LineIcon3 />
            </span>
          )}
        </div>
        {subTitle && (
          <div
            className={`${textCenter && "flex items-center gap-7 mx-auto "}`}
          >
            {line2 && (
              <span className="">
                <span className="md:block hidden">
                  <LineIcon2 />
                </span>
                <span className="md:hidden">
                  <LinkIcon4 />
                </span>
              </span>
            )}

            <Headings
              level={subTitleLevel}
              className={`text-[1.063rem] text-nowrap ${fontPrimary ? "primary-font" : "secondary-font"} ${subTitleClassName} ${subTitleColor ? `text-${subTitleColor}` : "text-primary"} ${mdTextCenter ? "md:text-center" : ""
                } ${textCenter ? "text-center mx-auto" : ""} ${smTextCenter ? "max-md:text-center" : ""
                }`}
              heading={subTitle}
            />

            {line2 && (
              <span className="rotate-180 ">
                <span className="">
                  <span className="md:block hidden">
                    <LineIcon2 />
                  </span>
                  <span className="md:hidden">
                    <LinkIcon4 />
                  </span>
                </span>
              </span>
            )}
          </div>
        )}
      </div>
    </AnimateOnScroll>
  );
};

export default SectionHeading;

